  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.alpha = 15.2 + fr(1) * 1.2;        // ~15.2-16.4 keeps canonical double-scroll
  S.beta0 = 27.0 + fr(2) * 2.4;        // ~27-29.4
  S.rphase = fr(3) * 6.283;            // rotation phase
  S.hoff = fr(4);                      // palette offset
  // warmup off transient, then fill the ring
  let x = 0.62 + fr(5) * 0.2, y = 0.01, z = 0.0;
  const al = S.alpha, be = S.beta0, dt = 0.006;
