  for (let k = 0; k < N; k++) {
    for (let s = 0; s < 6; s++) { const dx = al*(y - x - gd(x)), dy = x - y + z, dz = -be*y; x += dx*dt; y += dy*dt; z += dz*dt; }
    S.px[k] = x; S.py[k] = y; S.pz[k] = z;
