if (S.cx == null) { S.cx = 0.6; S.cy = 0.01; S.cz = 0; S.head = 0; }

// ---- live integration: advance the trajectory & recycle oldest ring slots (perpetual novelty) ----
const sec = K.section | 0;
const beta = S.beta0 + (P.drift * 4.0) * Math.sin(K.t * 0.05 + sec * 0.7) + (sec % 3 - 1) * 0.6;
const al = S.alpha, dt = 0.006;
