const g = S.g; g.loadPixels(); const pix = g.pixels;
for (let o = 0; o < BW * BH; o++) {
  const d = cnt[o];
  const bri = d > 0 ? (1 - Math.exp(-d * kg)) : 0;
  let r, gg, bl;
  if (style === 'plasma') {
    const zc = d > 0 ? zac[o] / d : 0;
    const hh = hbase + bri * 150 + zc * 90 + K.t * 6;
    const c = irgb(hh, 0.85, Math.pow(bri, 0.8));
    r = c[0]; gg = c[1]; bl = c[2];
    r += 0.02; gg += 0.015; bl += 0.05;
  } else if (style === 'ember') {
    const t2 = bri;
    r = Math.min(1, t2 * 2.2); gg = Math.min(1, Math.max(0, t2 * 2.1 - 0.55)); bl = Math.min(1, Math.max(0, t2 * 3.4 - 2.3));
    r += 0.03; gg += 0.008; bl += 0.012;
  } else if (style === 'ice') {
    const t2 = bri;
    r = Math.min(1, Math.max(0, t2 * 2.4 - 1.1)); gg = Math.min(1, t2 * 1.7); bl = Math.min(1, 0.15 + t2 * 1.4);
    r += 0.012; gg += 0.03; bl += 0.07;
  } else if (style === 'pencil') {
    const paper = 0.86, graphite = Math.pow(bri, 0.85) * 0.82;
    const gr = paper - graphite;
    r = gr * 1.0; gg = gr * 0.99; bl = gr * 0.95;
  } else { // double-scroll (default): magenta scroll / cyan scroll / gold bridge
    const cc = d > 0 ? col[o] / d : 0;      // -1 magenta .. 0 gold .. +1 cyan
    let hue;
    if (cc < 0) hue = 45 + (-cc) * (45 - (-30));      // gold(45) -> magenta(315 via -30 wrap)
    else hue = 45 + cc * (185 - 45);                  // gold(45) -> cyan(185)
    const c = irgb(hue, 0.82 - bri * 0.18, Math.pow(bri, 0.82));
    r = c[0]; gg = c[1]; bl = c[2];
    r += 0.035; gg += 0.028; bl += 0.075;            // deep-blue ambient ground
  }
  if (spark > 0.001) { r += spark * bri * 0.4; gg += spark * bri * 0.4; bl += spark * bri * 0.4; }
  const q = o * 4;
  pix[q]   = r < 0 ? 0 : r > 1 ? 255 : r * 255;
  pix[q+1] = gg < 0 ? 0 : gg > 1 ? 255 : gg * 255;
  pix[q+2] = bl < 0 ? 0 : bl > 1 ? 255 : bl * 255;
